useEffect(() => {
  const token = localStorage.getItem('token');
  if (token) {
    api.get('/api/users/me')
      .then(res => {
        setUser(res.data);
      })
      .catch((error) => {
        console.error('Failed to fetch user:', error);
        localStorage.removeItem('token');
        setUser(null);
      })
      .finally(() => setLoading(false));
  } else {
    setLoading(false);
  }
}, []);